export const VF3_VARIANT_IDS = ['vf3base', 'vf3eco', 'vf3plus'] as const;
export type Vf3VariantId = (typeof VF3_VARIANT_IDS)[number];

export function isVf3Variant(id: string): id is Vf3VariantId {
  return (VF3_VARIANT_IDS as readonly string[]).includes(id);
}

